/// Run `f` with errno 0 and the flags clear; errno and the flags it leaves.
fn observe(f: impl FnOnce()) -> (i32, Flags) {
    liella_boundary::errno::set_raw(0);
    fpu::clear(&CSys, Flags::ALL);
    f();
    (liella_boundary::errno::get(), fpu::test(&CSys, Flags::ALL))
}

/// `observe(f)` with the caller's MXCSR set to `mx` for the call; the caller's word is restored.
// ARCH(x86_64): the caller's MXCSR (FTZ, DAZ, rounding) around a call; FPCR on aarch64 (A-9)
fn observe_with_ctl(mx: u32, f: impl FnOnce()) -> (i32, Flags) {
    use liella_kernel::machine::Machine;
    // ARCH(x86_64): save, set and restore the caller's MXCSR; FPCR on aarch64 (A-9)
    let saved = CSys.mxcsr();
    // ARCH(x86_64): set the caller's MXCSR
    CSys.set_mxcsr(mx);
    let seen = observe(f);
    // ARCH(x86_64): restore the caller's MXCSR
    CSys.set_mxcsr(saved);
    seen
}

/// `observe(f)` with the x87 control word set to `cw` for the call; the caller's word is restored.
// ARCH(x86_64): the x87 control word (precision control); no such unit on aarch64 (A-9)
fn observe_with_cw(cw: u16, f: impl FnOnce()) -> (i32, Flags) {
    use liella_kernel::machine::Machine;
    // ARCH(x86_64): save, set and restore the x87 control word; no x87 on aarch64 (A-9)
    let saved = CSys.x87_control();
    // ARCH(x86_64): set the x87 control word
    CSys.set_x87_control(cw);
    let seen = observe(f);
    // ARCH(x86_64): restore the x87 control word
    CSys.set_x87_control(saved);
    seen
}

/// MXCSR rounding-control field (bits 13-14) and the matching `fesetround` argument (x87 RC,
/// bits 10-11): nearest, down, up, toward zero.
// ARCH(x86_64): x87 rounding-control encodings of `fesetround`; FE_* values on aarch64 (A-9)
const ROUND_DIRECTIONS: [(u32, i32); 4] = [(0, 0), (1, 0x400), (2, 0x800), (3, 0xc00)];

/// The `double` hypot kernel on the hardware root (`hot::Hw`, `sqrtsd`; LIBM-HYPOT-DIRECTED) is
/// the exact path (D-10.13) in every direction, value bits and status, on the math test's hard
/// pairs (ties, exact roots, roots just off a midpoint, the subnormal and overflow edges); the
/// `hypot` entry under each `fesetround` direction gives the same bits, errno and flags (a
/// directed call runs that kernel on `sqrtsd` in the default MXCSR).
#[test]
fn hypot_on_the_hardware_root_is_the_exact_path_in_every_direction() {
    // Clauses: s10_3_c_0 (D-10.104).
    use liella_boundary::hot::Hw;
    use liella_math::{invtrig, pow, MathError, Rounding};
    let errno_of = |e: MathError| if e == MathError::Range { 34 } else { 0 };
    let pairs: Vec<(f64, f64)> = hypot_pairs::hard_pairs().into_iter().flat_map(|(x, y)| [(x, y), (-y, x)]).collect();
    let dirs = [(0, Rounding::Nearest), (0x400, Rounding::Down), (0x800, Rounding::Up), (0xc00, Rounding::Zero)];
    for &(x, y) in &pairs {
        for (_, mode) in dirs {
            let (w, ws) = pow::hypot_exact::<f64>(x, y, mode);
            let (g, gs) = invtrig::hypot_rounded::<Hw>(x, y, mode).expect("a finite pair");
            assert!(g.to_bits() == w.to_bits() && gs == ws, "hypot({x:e}, {y:e}) {mode:?}: kernel on sqrtsd {g:e} {gs:?}, exact {w:e} {ws:?}: hardware kernel FAILED");
        }
    }
    for (rc, mode) in dirs {
        assert_eq!(liella_boundary::posix::s10_math::fesetround(rc), 0);
        for &(x, y) in &pairs {
            let (w, ws) = pow::hypot_exact::<f64>(x, y, mode);
            let mut got = 0;
            let seen = observe(|| got = m::hypot(x, y).to_bits());
            let want = (w.to_bits(), (errno_of(ws.error), Flags(ws.flags.0)));
            assert!((got, seen) == want, "hypot({x:e}, {y:e}) {mode:?}: entry {:e} {seen:?}, exact {w:e} {:?}: directed entry FAILED", f64::from_bits(got), want.1);
        }
    }
    assert_eq!(liella_boundary::posix::s10_math::fesetround(0), 0);
}

#[test]
fn math_translation_reports_errno_flags_and_out_parameters() {
    // Clauses: s10_0_f_0, s10_0_c_0.
    assert_eq!(observe(|| assert!(m::sqrt(-1.0).is_nan())), (33, Flags::INVALID)); // EDOM
    assert_eq!(observe(|| assert!(m::ldexpf(1.0, 200).is_infinite())), (34, Flags(0x28))); // ERANGE
    assert_eq!(observe(|| assert_eq!(m::lrint(1e300), i64::MIN)), (0, Flags::INVALID));
    assert_eq!(observe(|| assert_eq!(m::logb(0.0), f64::NEG_INFINITY)), (0, Flags::DIVBYZERO));
    let mut e = 0;
    assert_eq!(m::frexp(48.0, Some(&mut e)), 0.75);
    assert_eq!(e, 6);
    let mut q = 99;
    assert_eq!(m::remquo(7.5, 2.0, Some(&mut q)), -0.5);
    assert_eq!(q, 4);
    let mut ip = LdBits::from_bits(0);
    let half = LdBits::from_bits((0x3ffeu128 << 64) | (1u128 << 63));
    let two_and_half = LdBits::from_bits((0x4000u128 << 64) | (0xa0u128 << 56));
    assert_eq!(m::liella_modfl_bits(two_and_half, Some(&mut ip)).to_bits(), half.to_bits());
    assert_eq!(ip.to_bits(), (0x4000u128 << 64) | (1u128 << 63));
    let mut out = 0.0f64;
    assert_eq!(m::setpayload(Some(&mut out), 5.0), 0);
    assert_eq!(out.to_bits(), 0x7ff8_0000_0000_0005);
    assert_eq!(m::totalorder(Some(&-0.0), Some(&0.0)), 1);
    assert_eq!(observe(|| assert_eq!(m::fromfp(1e10, 0, 8), 127)), (33, Flags::INVALID));
    fpu::clear(&CSys, Flags::ALL);
}

/// The caller's MXCSR around an elementary function `f`, set to `mxcsr` before the call: the
/// result's bits and MXCSR after it.
// ARCH(x86_64): sets and reads the caller's MXCSR around the call; FPCR/FPSR on aarch64 (A-9)
fn around(mxcsr: u32, f: impl FnOnce() -> u64) -> (u64, u32) {
    let saved = fpu::enter_default(&CSys);
    fpu::leave(&CSys, mxcsr);
    let v = f();
    let after = fpu::enter_default(&CSys);
    fpu::leave(&CSys, saved);
    (v, after)
}

/// The `double` exp, exp2, log, log2, log10, pow and exp10 exports as `(name, export, reference)`:
/// the export through the C ABI entry, the reference `liella-math`'s accurate entry.
#[allow(clippy::type_complexity)]
fn double_fast_entries() -> [(&'static str, fn(f64, f64) -> f64, fn(f64, f64, liella_math::Rounding) -> f64); 7] {
    use liella_math::real::Real;
    [
        ("exp", |x, _| m::exp(x), |x, _, r| Real::exp(x, r).0),
        ("exp2", |x, _| m::exp2(x), |x, _, r| Real::exp2(x, r).0),
        ("log", |x, _| m::log(x), |x, _, r| Real::log(x, r).0),
        ("log2", |x, _| m::log2(x), |x, _, r| Real::log2(x, r).0),
        ("log10", |x, _| m::log10(x), |x, _, r| Real::log10(x, r).0),
        ("pow", |x, y| m::pow(x, y), |x, y, r| Real::pow(x, y, r).0),
        ("exp10", |x, _| m::exp10(x), |x, _, r| Real::exp10(x, r).0),
    ]
}

/// Arguments over and around the fast domains: the refused edges (specials, exact cases, tiny and
/// huge, subnormal), then pseudo-random `(x, y)` pairs at every scale.
fn double_fast_arguments() -> Vec<(f64, f64)> {
    double_fast_arguments_seeded(6000, 0x9e37_79b9_7f4a_7c15)
}

/// The special and edge arguments plus `2·n` random pairs from `seed` ([`double_fast_arguments`]).
fn double_fast_arguments_seeded(n: u64, seed: u64) -> Vec<(f64, f64)> {
    let edges = [
        0.0, -0.0, 1.0, -1.0, 2.0, 0.5, 3.0, 10.0, 100.0, 1e22, 1e23, 1e-5, 8.673_617_379_884_035e-19, 1e-19, 707.9, 708.0,
        709.7, 710.0, -707.9, -708.0, -740.0, -745.5, 1020.9, 1021.0, -1021.5, 1023.5, -1074.5, 1e-310, 2.2250738585072014e-308,
        f64::MAX, f64::INFINITY, f64::NEG_INFINITY, f64::NAN, 0.75, 1.5, -2.5, 1e300, 4.0, 9.0, 27.0, 1.0 + f64::EPSILON,
        1.0 - f64::EPSILON / 2.0, 22.0, 23.0, 24.0, -22.0, 306.9, 307.0, -306.9, -307.0, -307.5,
    ];
    let ys = [0.5, 1.5, -1.0, 2.0, 3.0, 1.0 / 2048.0, 1.0 / 4096.0, 0.1, -0.3, 7.25, 1e-61, 1e-59, 1e12, 3e12, 1e20, 300.5, -0.0];
    let mut v: Vec<(f64, f64)> = Vec::new();
    for &x in &edges {
        for &y in &ys {
            v.push((x, y));
        }
    }
    let mut s = seed;
    let mut next = || {
        s = s.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1_442_695_040_888_963_407);
        s
    };
    for i in 0..n {
        // x: a random mantissa at a random scale in [2^-1030, 2^1030); y: small to large.
        let (a, b, c) = (next(), next(), next());
        let exponent = if i & 1 == 1 { (b % 120).wrapping_add(970) } else { ((b >> 8) % 2046).wrapping_add(1) };
        let x = f64::from_bits((a >> 12) | (exponent << 52));
        let y = f64::from_bits((c >> 12) | (((c >> 3) % 60).wrapping_add(990) << 52));
        v.push((x, if a & 1 == 0 { y } else { -y }));
        v.push((-x * 0.001, y)); // negative exp arguments
    }
    v
}

// ARCH(x86_64): the in-place fast entry of the double exp/log/pow exports (s10_0_f_0); FPCR/FPSR on aarch64 (A-9)
#[test]
fn math_double_fast_entry_matches_the_envelope_in_every_mode() {
    // Clauses: s10_0_f_0.
    // Round to nearest with the default control word takes the in-place fast entry; DAZ set
    // (normal arguments: no effect on the value) forces the full envelope. Bits, flags and errno
    // must agree. The directed modes must match the accurate path of liella-math.
    let (checked, mut bad) = double_fast_entry_mismatches(&double_fast_arguments());
    let n = bad.len();
    bad.truncate(24);
    assert!(n == 0, "{n} mismatches, the first:\n{}", bad.join("\n"));
    assert!(checked > 60_000, "{checked}");
    fpu::clear(&CSys, Flags::ALL);
}

// ARCH(x86_64): the in-place fast entry of the double exp/log/pow exports (s10_0_f_0); FPCR/FPSR on aarch64 (A-9)
#[test]
fn math_double_fast_entry_stays_out_of_place_in_a_non_default_mode() {
    // Clauses: s10_0_f_0.
    // The fast path may run in place only under the default control word; under any other word
    // the entry switches to the default one before computing (D-10.13). Every rounding direction,
    // with and without FTZ and DAZ: the result is liella-math's accurate one in that direction and
    // MXCSR after the call is the caller's word with exactly the reference flags added, nothing
    // else. Values alone cannot show which path ran (the kernels' rounding tests also hold in the
    // caller's direction); a subnormal argument can: the fast domain tests compare it, raising the
    // denormal-operand bit in hardware, which the entry never leaves in the caller's word.
    use liella_math::Rounding;
    use liella_math::real::Real;
    let args = [(0.75, 2.5), (1.5, 0.3), (3.7, -1.7), (10.5, 7.25), (123.456, 0.1), (1e-310, 0.3), (5e-320, -0.3)]; // every result normal (FTZ)
    // The refused specials answered in place in the default word (ruling #2378) and the signalling NaN that is not.
    let specials = [(f64::NAN, 0.3), (f64::from_bits(0x7ff4_0000_0000_0000), 0.3), (f64::INFINITY, 0.3), (f64::NEG_INFINITY, 0.3)];
    let args: Vec<(f64, f64)> = args.into_iter().chain(specials).collect();
    let modes = [Rounding::Nearest, Rounding::Down, Rounding::Up, Rounding::Zero];
    let (mut checked, mut bad) = (0usize, Vec::new());
    for (name, f, _) in double_fast_entries().into_iter().chain(double_trig_entries()) {
        let trig = double_trig_entries().iter().any(|e| e.0 == name);
        for &(x, y) in &args {
            if trig && x.is_subnormal() {
                continue; // sin x and tan x are about x: a subnormal result, flushed under FTZ
            }
            for (rc, &mode) in (0u32..).zip(modes.iter()) {
                let (want, st) = match name {
                    "sin" => Real::sin(x, mode),
                    "cos" => Real::cos(x, mode),
                    "tan" => Real::tan(x, mode),
                    "sincos.sin" => (Real::sincos(x, mode).0 .0, Real::sincos(x, mode).1),
                    "sincos.cos" => (Real::sincos(x, mode).0 .1, Real::sincos(x, mode).1),
                    "exp" => Real::exp(x, mode),
                    "exp2" => Real::exp2(x, mode),
                    "log" => Real::log(x, mode),
                    "log2" => Real::log2(x, mode),
                    "log10" => Real::log10(x, mode),
                    "exp10" => Real::exp10(x, mode),
                    _ => Real::pow(x, y, mode),
                };
                // 0x3f: every flag already sticky in the caller's word, so leaving the word means
                // writing it back even when the result raises nothing new.
                for extra in [0, 0x8000, 0x40, 0x8040, 0x3f, 0x803f] {
                    if extra & 0x40 != 0 && x < f64::MIN_POSITIVE {
                        continue; // DAZ reads a subnormal argument as zero: another function value
                    }
                    let word = 0x1f80 | (rc << 13) | extra;
                    let got = around(word, || f(x, y).to_bits());
                    let need = (want.to_bits(), word | u32::from(st.flags.0));
                    if got != need {
                        bad.push(format!("{name}({x:e}, {y:e}) word {word:x}: {got:x?} vs {need:x?}"));
                    }
                    checked = checked.saturating_add(1);
                }
            }
        }
    }
    assert!(bad.is_empty(), "{} mismatches:\n{}", bad.len(), bad.join("\n"));
    assert!(checked > 500, "{checked}");
    fpu::clear(&CSys, Flags::ALL);
}

#[test]
fn math_double_fast_entry_stays_out_of_place_under_an_unmasked_trap() {
    // Clauses: s10_0_f_0.
    // A caller's word with one exception unmasked is not the default control word either, so the
    // fast entries switch to the default one before any arithmetic (D-10.13; the MXCSR read and
    // the operand barrier are D-X.44's inline forms). One test per mask the arguments' results
    // never raise: denormal operand, divide-by-zero, overflow, underflow (invalid and inexact
    // would trap on the entry's own legitimate raise). In place, a subnormal argument's domain
    // comparison would trap on the unmasked denormal-operand bit, or leave that bit in the
    // caller's word; out of place the result is liella-math's and MXCSR is the caller's word
    // with exactly the reference flags added, in every rounding direction.
    use liella_math::Rounding;
    use liella_math::real::Real;
    let args: [(f64, f64); 6] = [(0.75, 2.5), (1.5, 0.3), (3.7, -1.7), (10.5, 7.25), (1e-310, 0.3), (5e-320, -0.3)];
    let modes = [Rounding::Nearest, Rounding::Down, Rounding::Up, Rounding::Zero];
    let (mut checked, mut bad) = (0usize, Vec::new());
    for (name, f, _) in double_fast_entries().into_iter().chain(double_trig_entries()) {
        let trig = double_trig_entries().iter().any(|e| e.0 == name);
        for &(x, y) in &args {
            if trig && x.is_subnormal() {
                continue; // sin x and tan x are about x: a subnormal result raises underflow
            }
            for (rc, &mode) in (0u32..).zip(modes.iter()) {
                let (want, st) = match name {
                    "sin" => Real::sin(x, mode),
                    "cos" => Real::cos(x, mode),
                    "tan" => Real::tan(x, mode),
                    "sincos.sin" => (Real::sincos(x, mode).0 .0, Real::sincos(x, mode).1),
                    "sincos.cos" => (Real::sincos(x, mode).0 .1, Real::sincos(x, mode).1),
                    "exp" => Real::exp(x, mode),
                    "exp2" => Real::exp2(x, mode),
                    "log" => Real::log(x, mode),
                    "log2" => Real::log2(x, mode),
                    "log10" => Real::log10(x, mode),
                    "exp10" => Real::exp10(x, mode),
                    _ => Real::pow(x, y, mode),
                };
                for unmask in [0x100u32, 0x200, 0x400, 0x800] {
                    let word = (0x1f80 & !unmask) | (rc << 13);
                    let got = around(word, || f(x, y).to_bits());
                    let need = (want.to_bits(), word | u32::from(st.flags.0));
                    if got != need {
                        bad.push(format!("{name}({x:e}, {y:e}) word {word:x}: {got:x?} vs {need:x?}"));
                    }
                    checked = checked.saturating_add(1);
                }
            }
        }
    }
    assert!(bad.is_empty(), "{} mismatches:\n{}", bad.len(), bad.join("\n"));
    assert!(checked > 500, "{checked}");
    fpu::clear(&CSys, Flags::ALL);
}

/// Every argument of `args` through each double fast entry ([`math_double_fast_entry_matches_the_envelope_in_every_mode`]):
/// the number checked and one line per mismatch.
fn double_fast_entry_mismatches(args: &[(f64, f64)]) -> (usize, Vec<String>) {
    fast_entry_mismatches(&double_fast_entries(), args)
}

/// The `double` sin, cos, tan and sincos exports (LIBM-F64-TRIG-TIER) as [`double_fast_entries`]
/// does; `sincos` twice, once per result.
#[allow(clippy::type_complexity)]
fn double_trig_entries() -> [(&'static str, fn(f64, f64) -> f64, fn(f64, f64, liella_math::Rounding) -> f64); 5] {
    use liella_math::real::Real;
    [
        ("sin", |x, _| m::sin(x), |x, _, r| Real::sin(x, r).0),
        ("cos", |x, _| m::cos(x), |x, _, r| Real::cos(x, r).0),
        ("tan", |x, _| m::tan(x), |x, _, r| Real::tan(x, r).0),
        ("sincos.sin", |x, _| sincos_pair(x).0, |x, _, r| Real::sincos(x, r).0 .0),
        ("sincos.cos", |x, _| sincos_pair(x).1, |x, _, r| Real::sincos(x, r).0 .1),
    ]
}

/// `sincos` through its export.
fn sincos_pair(x: f64) -> (f64, f64) {
    let (mut s, mut c) = (0.0, 0.0);
    m::sincos(x, Some(&mut s), Some(&mut c));
    (s, c)
}

/// Trig arguments over and around the fast domain [2^-30, 2^20): the refused edges (zeros,
/// subnormals, 2^-339 and 2^-30, 2^20, huge, specials), a few ulps around the multiples of π/2 and
/// the cell edges k·π/64 ± π/128, then random values in every binade from 2^-36 to 2^23.
#[allow(clippy::arithmetic_side_effects, clippy::as_conversions)] // bounded sample arithmetic
fn double_trig_arguments() -> Vec<(f64, f64)> {
    let ulps = |c: f64, w: u64| (0..=2 * w).map(move |d| f64::from_bits(c.to_bits().wrapping_add(d).wrapping_sub(w)));
    let mut v: Vec<f64> = vec![0.0, f64::MIN_POSITIVE, 1e-310, f64::MAX, 1e300, f64::INFINITY, f64::NAN, 1.0, 0.5, 3.0, 1e5, 7e5];
    // 2^-360 and 2^-1000: below the in-place cubic's range (x³ would underflow and raise it).
    for c in [2f64.powi(-339), 2f64.powi(-30), 2f64.powi(20), 2f64.powi(-36), 2f64.powi(-200), 2f64.powi(-360), 2f64.powi(-1000)] {
        v.extend(ulps(c, 3));
    }
    let q = core::f64::consts::PI / 128.0;
    for k in (1u32..400).chain([1001, 4097, 65_535, 1_000_001, 8_000_001, 33_000_001, 42_000_001]) {
        v.extend(ulps(f64::from(k) * core::f64::consts::FRAC_PI_2, 2)); // n·π/2: cancellation, tan's poles
        v.extend(ulps(f64::from(2 * k + 1) * q, 1)); // the cell edges (2j + 1)·π/128
    }
    let mut s = 0x243f_6a88_85a3_08d3u64;
    let mut next = || {
        s = s.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1_442_695_040_888_963_407);
        s
    };
    for _ in 0..4000 {
        let (a, b) = (next(), next());
        v.push(2f64.powi((b % 60) as i32 - 36) * (1.0 + (a >> 12) as f64 * 2f64.powi(-52)));
    }
    let n = v.len();
    v.extend_from_within(..n);
    for x in v.iter_mut().skip(n) {
        *x = -*x;
    }
    v.into_iter().map(|x| (x, 0.0)).collect()
}

// ARCH(x86_64): the in-place fast entry of the double trig exports (s10_0_f_0); FPCR/FPSR on aarch64 (A-9)
#[test]
fn math_double_trig_fast_entry_matches_the_envelope_in_every_mode() {
    // Clauses: s10_0_f_0.
    // As math_double_fast_entry_matches_the_envelope_in_every_mode for sin, cos, tan and sincos
    // (LIBM-F64-TRIG-TIER): the in-place entry (default word) against the full envelope (DAZ), bits,
    // flags and errno; the directed modes against liella-math's accurate path. The arguments are
    // the trig hard cases: the domain edges, n·π/2 and the reduction cells' edges.
    let (checked, mut bad) = fast_entry_mismatches(&double_trig_entries(), &double_trig_arguments());
    let n = bad.len();
    bad.truncate(24);
    assert!(n == 0, "{n} mismatches, the first:\n{}", bad.join("\n"));
    assert!(checked > 50_000, "{checked}");
    fpu::clear(&CSys, Flags::ALL);
}

/// [`double_fast_entry_mismatches`] over the given entries.
#[allow(clippy::arithmetic_side_effects, clippy::type_complexity)] // counters over bounded test loops
fn fast_entry_mismatches(entries: &[(&'static str, fn(f64, f64) -> f64, fn(f64, f64, liella_math::Rounding) -> f64)], args: &[(f64, f64)]) -> (usize, Vec<String>) {
    let mut checked = 0usize;
    let mut bad = Vec::new();
    for &(name, f, reference) in entries {
        for &(x, y) in args {
            let sub = |a: f64| a != 0.0 && a.abs() < f64::MIN_POSITIVE;
            if sub(x) || sub(y) {
                continue;
            }
            let mut fast = (0, 0);
            let e_fast = observe(|| fast = around(0x1f80, || f(x, y).to_bits())).0;
            let mut full = (0, 0);
            let e_full = observe(|| full = around(0x1f80 | 0x40, || f(x, y).to_bits())).0;
            if (fast.0, fast.1 | 0x40, e_fast) != (full.0, full.1, e_full) {
                bad.push(format!("{name}({x:e}, {y:e}) nearest: {fast:x?} {e_fast} vs {full:x?} {e_full}"));
            }
            for (rc, mode) in [(1u32, liella_math::Rounding::Down), (2, liella_math::Rounding::Up), (3, liella_math::Rounding::Zero)] {
                let (bits, _) = around(0x1f80 | (rc << 13), || f(x, y).to_bits());
                let want = reference(x, y, mode).to_bits();
                if bits != want && !(f64::from_bits(bits).is_nan() && f64::from_bits(want).is_nan()) {
                    bad.push(format!("{name}({x:e}, {y:e}) rc {rc}: {bits:x} vs {want:x}"));
                }
            }
            checked += 1;
        }
    }
    (checked, bad)
}

/// The `float` hyperbolic exports as `(name, export, reference)` (LIBM-F32-HYPERBOLIC-3): the
/// export through its in-place fast entry, the reference `liella-math`'s accurate entry.
#[allow(clippy::type_complexity)]
fn float_hyperbolic_entries() -> [(&'static str, fn(f32) -> f32, fn(f32, liella_math::Rounding) -> f32); 6] {
    use liella_math::real::Real;
    [
        ("sinhf", |x| m::sinhf(x), |x, r| Real::sinh(x, r).0),
        ("coshf", |x| m::coshf(x), |x, r| Real::cosh(x, r).0),
        ("tanhf", |x| m::tanhf(x), |x, r| Real::tanh(x, r).0),
        ("asinhf", |x| m::asinhf(x), |x, r| Real::asinh(x, r).0),
        ("acoshf", |x| m::acoshf(x), |x, r| Real::acosh(x, r).0),
        ("atanhf", |x| m::atanhf(x), |x, r| Real::atanh(x, r).0),
    ]
}

// ARCH(x86_64): the in-place fast entry of the float hyperbolic exports (s10_0_f_0); FPCR/FPSR on aarch64 (A-9)
#[test]
#[allow(clippy::arithmetic_side_effects)] // counters over bounded test loops
fn math_float_hyperbolic_fast_entry_matches_the_envelope_in_every_mode() {
    // Clauses: s10_0_f_0.
    // Round to nearest with the default control word takes the in-place fast entry; DAZ set
    // (normal arguments: no effect on the value) forces the full envelope. Bits, flags and errno
    // must agree. The directed modes must match the accurate path of liella-math. Arguments: every
    // 2^16th `float` bit pattern of each sign (the fast domains and every refused range: zeros,
    // tiny, the 2^-26 cut, the overflow edges, |x| ≥ 1 for atanh, x ≤ 1 for acosh, infinities,
    // NaNs) and the edges of each fast domain.
    let edges: [f32; 16] = [
        1.490_116_1e-8, 1.490_116_2e-8, 0.75, 1.0, 1.000_000_1, 0.999_999_94, 9.499_999, 9.5, 88.999_99, 89.0, 89.499_99,
        89.5, 89.415_985, 1e30, f32::MAX, 2.5,
    ];
    let mut args: Vec<f32> = edges.iter().flat_map(|&x| [x, -x]).collect();
    args.extend((0u32..1 << 16).map(|i| f32::from_bits(i << 16 | (i & 0xffff))));
    let (mut checked, mut bad) = (0usize, Vec::new());
    for (name, f, reference) in float_hyperbolic_entries() {
        for &x in &args {
            if x != 0.0 && x.abs() < f32::MIN_POSITIVE {
                continue; // DAZ reads a subnormal argument as zero: another function value
            }
            let mut fast = (0, 0);
            let e_fast = observe(|| fast = around(0x1f80, || u64::from(f(x).to_bits()))).0;
            let mut full = (0, 0);
            let e_full = observe(|| full = around(0x1f80 | 0x40, || u64::from(f(x).to_bits()))).0;
            if (fast.0, fast.1 | 0x40, e_fast) != (full.0, full.1, e_full) {
                bad.push(format!("{name}({x:e}) nearest: {fast:x?} {e_fast} vs {full:x?} {e_full}"));
            }
            for (rc, mode) in [(1u32, liella_math::Rounding::Down), (2, liella_math::Rounding::Up), (3, liella_math::Rounding::Zero)] {
                let (bits, _) = around(0x1f80 | (rc << 13), || u64::from(f(x).to_bits()));
                let want = u64::from(reference(x, mode).to_bits());
                if bits != want && !(f32::from_bits(u32::try_from(bits).unwrap_or(0)).is_nan() && reference(x, mode).is_nan()) {
                    bad.push(format!("{name}({x:e}) rc {rc}: {bits:x} vs {want:x}"));
                }
            }
            checked += 1;
        }
    }
    let n = bad.len();
    bad.truncate(24);
    assert!(n == 0, "{n} mismatches, the first:\n{}", bad.join("\n"));
    assert!(checked > 380_000, "{checked}");
    fpu::clear(&CSys, Flags::ALL);
}

// ARCH(x86_64): the in-place fast entry of the float sincos export (s10_0_f_0); FPCR/FPSR on aarch64 (A-9)
#[test]
#[allow(clippy::arithmetic_side_effects)] // counters over bounded test loops
fn math_float_sincos_fast_entry_matches_the_envelope_in_every_mode() {
    // Clauses: s10_0_f_0.
    // sincosf's in-place entry (LIBM-SINCOS-SHARED, D-10.89) as the float hyperbolic test above:
    // round to nearest in the default word takes it, DAZ forces the full envelope, and both
    // results, the flags and errno must agree; the directed modes must give liella-math's
    // accurate pair. Arguments: every 2^16th `float` bit pattern of each sign (the fast range
    // 2^-26 <= |x| < 2^19 and every refused range) and the range's edges.
    use liella_math::real::Real;
    let pair = |x: f32| {
        let (mut s, mut c) = (0f32, 0f32);
        m::sincosf(x, Some(&mut s), Some(&mut c));
        u64::from(s.to_bits()) << 32 | u64::from(c.to_bits())
    };
    let edges: [f32; 6] = [1.490_116_1e-8, 1.490_116_2e-8, 524_287.97, 524_288.0, std::f32::consts::FRAC_PI_4, std::f32::consts::FRAC_PI_2];
    let mut args: Vec<f32> = edges.iter().flat_map(|&x| [x, -x]).collect();
    args.extend((0u32..1 << 16).map(|i| f32::from_bits(i << 16 | (i & 0xffff))));
    let (mut checked, mut bad) = (0usize, Vec::new());
    for &x in &args {
        if x != 0.0 && x.abs() < f32::MIN_POSITIVE {
            continue; // DAZ reads a subnormal argument as zero: another function value
        }
        let mut fast = (0, 0);
        let e_fast = observe(|| fast = around(0x1f80, || pair(x))).0;
        let mut full = (0, 0);
        let e_full = observe(|| full = around(0x1f80 | 0x40, || pair(x))).0;
        if (fast.0, fast.1 | 0x40, e_fast) != (full.0, full.1, e_full) {
            bad.push(format!("sincosf({x:e}) nearest: {fast:x?} {e_fast} vs {full:x?} {e_full}"));
        }
        for (rc, mode) in [(1u32, liella_math::Rounding::Down), (2, liella_math::Rounding::Up), (3, liella_math::Rounding::Zero)] {
            let (bits, _) = around(0x1f80 | (rc << 13), || pair(x));
            let ((s, c), _) = Real::sincos(x, mode);
            let want = u64::from(s.to_bits()) << 32 | u64::from(c.to_bits());
            if bits != want && !x.is_nan() {
                bad.push(format!("sincosf({x:e}) rc {rc}: {bits:x} vs {want:x}"));
            }
        }
        checked += 1;
    }
    let n = bad.len();
    bad.truncate(24);
    assert!(n == 0, "{n} mismatches, the first:\n{}", bad.join("\n"));
    assert!(checked > 60_000, "{checked}");
    fpu::clear(&CSys, Flags::ALL);
}

// ARCH(x86_64): the in-place fast entry of the double exp/log/pow exports (s10_0_f_0); FPCR/FPSR on aarch64 (A-9)
#[test]
#[ignore = "long sweep:cargo test -p liella-boundary --release --test s10_math_symbols -- --ignored --nocapture math_double_fast_entry_sweep"]
#[allow(clippy::arithmetic_side_effects)] // counters over bounded test loops
fn math_double_fast_entry_sweep() {
    // Clauses: s10_0_f_0. The fast-domain agreement sweep (MATH-M6-F64-FAST-ENTRY-2): LIELLA_FE_SWEEP_CHUNKS
    // chunks (default 200) of 2·10^6 random pairs each, every one through all seven fast entries as above.
    let chunks: u64 = std::env::var("LIELLA_FE_SWEEP_CHUNKS").ok().and_then(|v| v.parse().ok()).unwrap_or(200);
    // MATH-M6-F64-GAP-ROUND-TEST: also count which rounding step answers each in-place call
    // (liella_math::fast64::nearest_stage: 0 the constant test, 1 its miss settled by the exact
    // test, 2 the exact test alone, 3 the accurate path, 4 refused). The cap (coordinator #2071): a
    // miss rate (1 over 0 + 1) of at most 2^-12 per function; a miss costs one exact test (~30
    // instructions), so 2^-12 bounds its cost below 0.01 instructions per call.
    let names = ["exp", "exp2", "log", "log2", "log10", "pow", "exp10"];
    let mut stages = [[0u64; 5]; 7];
    let (mut checked, mut bad) = (0usize, Vec::new());
    for c in 0..chunks {
        let args = double_fast_arguments_seeded(1_000_000, 0x5eed_0000_0000_0001 ^ c.wrapping_mul(0x9e37_79b9_7f4a_7c15));
        for (which, row) in stages.iter_mut().enumerate() {
            for &(x, y) in &args {
                let code = usize::from(liella_math::fast64::nearest_stage(which, x, y));
                if let Some(n) = row.get_mut(code) {
                    *n += 1;
                }
            }
        }
        let (n, b) = double_fast_entry_mismatches(&args);
        checked += n;
        bad.extend(b);
        println!("chunk {c}: {checked} checked, {} mismatches", bad.len());
    }
    let mut over = Vec::new();
    for (name, s) in names.iter().zip(stages) {
        let tried = (s[0] + s[1]).max(1);
        let ppm = s[1] * 1_000_000 / tried;
        println!("stages {name}: near {} miss {} exact-only {} accurate {} refused {}; miss rate {ppm} ppm (cap 2^-12 = 244 ppm)", s[0], s[1], s[2], s[3], s[4]);
        if s[1] * 4096 > tried || s[0] == 0 {
            over.push(format!("{name} miss rate {ppm} ppm (near {})", s[0]));
        }
    }
    let n = bad.len();
    bad.truncate(24);
    assert!(n == 0, "{n} mismatches, the first:\n{}", bad.join("\n"));
    assert!(over.is_empty(), "near-test miss rate above the 2^-12 cap: {}", over.join("; "));
    fpu::clear(&CSys, Flags::ALL);
}

// ARCH(x86_64): the math envelope's MXCSR contract (s10_0_f_0); FPCR/FPSR on aarch64 (A-9)
#[test]
fn math_envelope_keeps_the_callers_mxcsr() {
    // Clauses: s10_0_f_0.
    // Default control word: the in-place path. An exact result leaves the caller's flags as they
    // were (the computation's own inexact is dropped), an inexact one adds only inexact.
    assert_eq!(around(0x1f80, || m::pow(2.0, 3.0).to_bits()), (8.0f64.to_bits(), 0x1f80));
    assert_eq!(around(0x1f80 | 0x10, || m::exp(0.0).to_bits()), (1.0f64.to_bits(), 0x1f90));
    let (_, mx) = around(0x1f80, || m::exp(0.5).to_bits());
    assert_eq!(mx, 0x1fa0);
    // Exceptional results the computation may form without the arithmetic that raises their
    // flags: the reported flags still reach MXCSR, and only they.
    assert_eq!(around(0x1f80, || m::log(0.0).to_bits()), (f64::NEG_INFINITY.to_bits(), 0x1f84));
    assert_eq!(around(0x1f80, || m::exp(1000.0).to_bits()), (f64::INFINITY.to_bits(), 0x1fa8));
    assert_eq!(around(0x1f80, || m::log(-1.0).to_bits()).1, 0x1f81);
    assert_eq!(around(0x1f80, || m::sqrt(-1.0).to_bits()).1, 0x1f81);
    // The caller's flush-to-zero and denormals-are-zero are honoured (owner ruling 2026-10-23,
    // D-10.22): under FTZ a subnormal result is a zero of its sign with underflow and inexact
    // raised (a subnormal operand whose result rounds to itself, an exact subnormal result);
    // under DAZ a subnormal operand is read as a zero of its sign. MXCSR comes back intact.
    let sub = f64::from_bits(1 << 40);
    let small: [extern "C" fn(f64) -> f64; 8] = [m::sin, m::tan, m::atan, m::asin, m::sinh, m::tanh, m::expm1, m::log1p];
    for (i, f) in small.iter().enumerate() {
        assert_eq!((i, around(0x9f80, || f(sub).to_bits())), (i, (0, 0x9f80 | 0x30)));
        assert_eq!((i, around(0x9f80, || f(-sub).to_bits())), (i, (1 << 63, 0x9f80 | 0x30)));
        assert_eq!((i, around(0x1fc0, || f(-sub).to_bits())), (i, (1 << 63, 0x1fc0)));
    }
    assert_eq!(around(0x9f80, || m::exp2(-1060.0).to_bits()), (0, 0x9f80 | 0x30));
    assert_eq!(around(0x9f80, || m::exp(-740.0).to_bits()), (0, 0x9f80 | 0x30));
    assert_eq!(around(0x1fc0, || m::exp(sub).to_bits()), (1.0f64.to_bits(), 0x1fc0));
    // Normal operands and normal results are the default word's, in every rounding direction,
    // under FTZ, DAZ and both; a subnormal one is flushed as above. `daz` is the same call with
    // its subnormal operands read as zeros of their sign; `w32` marks a `float` result.
    type Case<'a> = (&'a str, &'a dyn Fn() -> u64, Option<&'a dyn Fn() -> u64>, bool);
    let cases: [Case<'_>; 25] = [
        ("powf(1e-40,0.3)", &|| u64::from(m::powf(1e-40, 0.3).to_bits()), Some(&|| u64::from(m::powf(0.0, 0.3).to_bits())), true),
        ("powf(2.5,-97.3)", &|| u64::from(m::powf(2.5, -97.3).to_bits()), None, true),
        ("sin(1e-310)", &|| m::sin(1e-310).to_bits(), Some(&|| m::sin(0.0).to_bits()), false),
        ("tan(-5e-324)", &|| m::tan(-5e-324).to_bits(), Some(&|| m::tan(-0.0).to_bits()), false),
        ("sin(-2e-308)", &|| m::sin(-2e-308).to_bits(), Some(&|| m::sin(-0.0).to_bits()), false),
        ("exp(-744)", &|| m::exp(-744.0).to_bits(), None, false),
        ("exp(-708.5)", &|| m::exp(-708.5).to_bits(), None, false),
        ("exp2(-1070.3)", &|| m::exp2(-1070.3).to_bits(), None, false),
        ("pow(1.5e-160,2)", &|| m::pow(1.5e-160, 2.0).to_bits(), None, false),
        ("atan2(1e-300,1e10)", &|| m::atan2(1e-300, 1e10).to_bits(), None, false),
        ("erf(1e-310)", &|| m::erf(1e-310).to_bits(), Some(&|| m::erf(0.0).to_bits()), false),
        ("j1(1e-310)", &|| m::j1(1e-310).to_bits(), Some(&|| m::j1(0.0).to_bits()), false),
        ("expf(-100)", &|| u64::from(m::expf(-100.0).to_bits()), None, true),
        ("erff(1e-40)", &|| u64::from(m::erff(1e-40).to_bits()), Some(&|| u64::from(m::erff(0.0).to_bits())), true),
        ("log(1e-310)", &|| m::log(1e-310).to_bits(), Some(&|| m::log(0.0).to_bits()), false),
        ("log2(5e-320)", &|| m::log2(5e-320).to_bits(), Some(&|| m::log2(0.0).to_bits()), false),
        ("log10(1e-315)", &|| m::log10(1e-315).to_bits(), Some(&|| m::log10(0.0).to_bits()), false),
        ("cbrt(1e-320)", &|| m::cbrt(1e-320).to_bits(), Some(&|| m::cbrt(0.0).to_bits()), false),
        ("atan2(3e-310,1e-310)", &|| m::atan2(3e-310, 1e-310).to_bits(), Some(&|| m::atan2(0.0, 0.0).to_bits()), false),
        ("atan2f(1e-38,1e5)", &|| u64::from(m::atan2f(1e-38, 1e5).to_bits()), Some(&|| u64::from(m::atan2f(0.0, 1e5).to_bits())), true),
        ("logf(1e-40)", &|| u64::from(m::logf(1e-40).to_bits()), Some(&|| u64::from(m::logf(0.0).to_bits())), true),
        // The hardware square root (M6-2) runs under the caller's word: DAZ reads 0.
        ("sqrt(1e-310)", &|| m::sqrt(1e-310).to_bits(), Some(&|| m::sqrt(0.0).to_bits()), false),
        ("sqrt(5e-324)", &|| m::sqrt(5e-324).to_bits(), Some(&|| m::sqrt(0.0).to_bits()), false),
        ("sqrtf(1e-40)", &|| u64::from(m::sqrtf(1e-40).to_bits()), Some(&|| u64::from(m::sqrtf(0.0).to_bits())), true),
        ("sqrt(2)", &|| m::sqrt(2.0).to_bits(), None, false),
    ];
    let flush = |b: u64, w32: bool| -> Option<u64> {
        let (exp, sign) = if w32 { (0x7f80_0000, 1 << 31) } else { (0x7ff0_0000_0000_0000, 1 << 63) };
        (b & exp == 0 && b & !sign != 0).then_some(b & sign)
    };
    for (name, f, daz, w32) in cases {
        for rc in 0..4u32 {
            let base = 0x1f80 | (rc << 13);
            // Bit 1 (denormal operand, outside FE_ALL_EXCEPT) aside: the hardware square root
            // sets it for a subnormal operand in place; the software path not.
            let read = |bit: u32| match daz {
                Some(g) if bit & 0x40 != 0 => around(base, g),
                _ => around(base, f),
            };
            for bit in [0x8000, 0x40, 0x8040] {
                let (want, mx) = read(bit);
                let (want, mx) = match flush(want, w32) {
                    Some(z) if bit & 0x8000 != 0 => (z, mx | 0x30),
                    _ => (want, mx),
                };
                let (v, got) = around(base | bit, f);
                assert_eq!((name, rc, bit, v, got & !2), (name, rc, bit, want, (mx | bit) & !2));
            }
        }
    }
    // The default-word results those compare with: the subnormals and logarithms they should be.
    assert_eq!(around(0x1f80, || m::exp(-744.0).to_bits()).0, 2);
    assert_eq!(around(0x1f80, || u64::from(m::expf(-100.0).to_bits())).0, 0x1b);
    assert!((m::log2(5e-320) + 1060.69).abs() < 0.01);
    assert!((m::log(1e-310) + 713.8).abs() < 0.1);
    // Directed modes switch and still round in the caller's direction.
    let up = around(0x5f80, || m::exp(0.5).to_bits());
    let down = around(0x3f80, || m::exp(0.5).to_bits());
    assert_eq!((up.1, down.1), (0x5fa0, 0x3fa0));
    assert!(up.0 > down.0);
    fpu::clear(&CSys, Flags::ALL);
}

// ARCH(x86_64): the math envelope's MXCSR contract (s10_0_f_0); FPCR/FPSR on aarch64 (A-9)
#[test]
fn math_envelope_keeps_a_result_that_is_not_tiny_under_the_callers_ftz() {
    // Clauses: s10_0_f_0.
    // The tininess edge is x86's: tiny AFTER rounding with an unbounded exponent (probed on Haswell-EP host,
    // see `ftz_flushes_the_tininess_edge` in mathret.rs). A result that is exactly the smallest
    // normal and not tiny is kept under the caller's FTZ, without underflow.
    let edge = f64::MIN_POSITIVE;
    assert_eq!(around(0x9f80, || m::exp2(-1022.0).to_bits()), (edge.to_bits(), 0x9f80));
    assert_eq!(around(0x9f80, || u64::from(m::exp2f(-126.0).to_bits())), (u64::from(f32::MIN_POSITIVE.to_bits()), 0x9f80));
    fpu::clear(&CSys, Flags::ALL);
}

/// What a software-path case returns: a `double`, a `float`, an integer (never flushed) or a
/// `float`/`double` the reference never flushes under FTZ (an operand-returning form or an x87
/// narrowing: probed, #1549, D-10.22).
#[derive(Clone, Copy)]
enum Res {
    F64,
    F32,
    Int,
    Kept,
}

/// A normal long double 1.0 * 2^(biased - 16383) (explicit integer bit).
fn ld_pow2(biased: u128) -> LdBits {
    LdBits::from_bits((biased << 64) | (1u128 << 63))
}

// ARCH(x86_64): the caller's MXCSR FTZ/DAZ through the software paths (s10_0_f_0); FPCR on aarch64 (A-9)
#[test]
fn math_software_paths_honour_the_callers_ftz_and_daz() {
    // Clauses: s10_0_f_0.
    // D-10.22 (owner ruling 2026-10-23, MATH-M6-FPENV-HONOR-REST): the families outside the
    // envelope (`mret::Soft`: fma, fdim, the narrowing operations, nextafter, ldexp/scalbn, the
    // rounding and min/max families, the integer results, out-parameter forms, hypot) follow the
    // envelope's rule. Under DAZ a `float`/`double` operand that is subnormal is read as a zero of
    // its sign (`daz` is the same call with those zeros); under FTZ a `float`/`double` result that
    // is subnormal is a zero of its sign with underflow and inexact; under both, both. Normal
    // operands and results are the default word's, in every rounding direction. Probed against the
    // reference under FTZ, DAZ and both (#1549, `Res::Kept`): `long double` operands are x87 values
    // and the narrowing from them (`daddl`, `faddl`, `fmull`) is never flushed; the min/max forms
    // return the operand as DAZ reads it (fmax, fminmag) or the raw operand DAZ's comparison picks
    // (fmaximum*), never flushed; nextafter gives `y` for operands equal as DAZ reads them, else
    // steps the raw `x`; nextup/nextdown/nexttoward step the raw `x`; a step from an `x` DAZ reads
    // as zero raises nothing (the `daz` closures there are bit patterns: no flags); fabs and
    // copysign are unchanged in every mode; the rounding family reads its operand as DAZ does.
    type Case<'a> = (&'a str, &'a dyn Fn() -> u64, Option<&'a dyn Fn() -> u64>, Res);
    let d = |v: f64| v.to_bits();
    let f = |v: f32| u64::from(v.to_bits());
    let cases: [Case<'_>; 57] = [
        ("fma(1e-160,1e-160,0)", &|| d(m::fma(1e-160, 1e-160, 0.0)), None, Res::F64),
        ("fma(1e-310,2,0)", &|| d(m::fma(1e-310, 2.0, 0.0)), Some(&|| d(m::fma(0.0, 2.0, 0.0))), Res::F64),
        ("fma(1.5,2,0.1)", &|| d(m::fma(1.5, 2.0, 0.1)), None, Res::F64),
        ("fmaf(1e-40,1,-0)", &|| f(m::fmaf(1e-40, 1.0, -0.0)), Some(&|| f(m::fmaf(0.0, 1.0, -0.0))), Res::F32),
        ("fdim(3e-308,1e-308)", &|| d(m::fdim(3e-308, 1e-308)), Some(&|| d(m::fdim(3e-308, 0.0))), Res::F64),
        ("fdim(5,1.1)", &|| d(m::fdim(5.0, 1.1)), None, Res::F64),
        ("fadd(1e-39,1e-39)", &|| f(m::fadd(1e-39, 1e-39)), None, Res::F32),
        ("fmul(1e-20,1e-20)", &|| f(m::fmul(1e-20, 1e-20)), None, Res::F32),
        ("fsqrt(1e-80)", &|| f(m::fsqrt(1e-80)), None, Res::F32),
        ("fdiv(1,3)", &|| f(m::fdiv(1.0, 3.0)), None, Res::F32),
        ("ffma(1e-310,1,1e-39)", &|| f(m::ffma(1e-310, 1.0, 1e-39)), Some(&|| f(m::ffma(0.0, 1.0, 1e-39))), Res::F32),
        ("daddl(2^-1070,0)", &|| d(m::liella_daddl_bits(ld_pow2(16383 - 1070), LdBits::from_bits(0))), None, Res::Kept),
        ("faddl(2^-140,0)", &|| f(m::liella_faddl_bits(ld_pow2(16383 - 140), LdBits::from_bits(0))), None, Res::Kept),
        ("fmull(2^-70,2^-70)", &|| f(m::liella_fmull_bits(ld_pow2(16383 - 70), ld_pow2(16383 - 70))), None, Res::Kept),
        ("faddl(1,2^-30)", &|| f(m::liella_faddl_bits(ld_pow2(16383), ld_pow2(16383 - 30))), None, Res::Kept),
        ("ldexp(1,-1070)", &|| d(m::ldexp(1.0, -1070)), None, Res::F64),
        ("ldexp(1e-310,4)", &|| d(m::ldexp(1e-310, 4)), Some(&|| d(m::ldexp(0.0, 4))), Res::F64),
        ("scalbn(3,-1060)", &|| d(m::scalbn(3.0, -1060)), None, Res::F64),
        ("ldexpf(1.5,-140)", &|| f(m::ldexpf(1.5, -140)), None, Res::F32),
        ("ldexp(1.25,-20)", &|| d(m::ldexp(1.25, -20)), None, Res::F64),
        ("nextafter(0,1)", &|| d(m::nextafter(0.0, 1.0)), Some(&|| 1), Res::Kept),
        ("nextafter(1e-310,1)", &|| d(m::nextafter(1e-310, 1.0)), Some(&|| d(1e-310) + 1), Res::Kept),
        ("nextafter(1e-310,2e-310)", &|| d(m::nextafter(1e-310, 2e-310)), Some(&|| d(2e-310)), Res::Kept),
        ("nextafterf(-0,-1)", &|| f(m::nextafterf(-0.0, -1.0)), Some(&|| 0x8000_0001), Res::Kept),
        ("nextup(-5e-324)", &|| d(m::nextup(-5e-324)), Some(&|| 1 << 63), Res::Kept),
        ("nextdown(1e-310)", &|| d(m::nextdown(1e-310)), Some(&|| d(1e-310) - 1), Res::Kept),
        ("nexttoward(1e-310,1)", &|| d(m::liella_nexttoward_bits(1e-310, ld_pow2(16383))), Some(&|| d(1e-310) + 1), Res::Kept),
        ("nexttowardf(1e-40,-1)", &|| f(m::liella_nexttowardf_bits(1e-40, ld_pow2(16383 + (1 << 15)))), Some(&|| f(1e-40) - 1), Res::Kept),
        ("nextafter(1,2)", &|| d(m::nextafter(1.0, 2.0)), None, Res::Kept),
        ("ceil(1e-310)", &|| d(m::ceil(1e-310)), Some(&|| d(m::ceil(0.0))), Res::F64),
        ("floor(-1e-310)", &|| d(m::floor(-1e-310)), Some(&|| d(m::floor(-0.0))), Res::F64),
        ("rintf(1e-40)", &|| f(m::rintf(1e-40)), Some(&|| f(m::rintf(0.0))), Res::F32),
        ("ceil(2.5)", &|| d(m::ceil(2.5)), None, Res::F64),
        ("trunc(-1e-310)", &|| d(m::trunc(-1e-310)), Some(&|| d(m::trunc(-0.0))), Res::F64),
        ("round(1e-310)", &|| d(m::round(1e-310)), Some(&|| d(m::round(0.0))), Res::F64),
        ("nearbyint(-1e-310)", &|| d(m::nearbyint(-1e-310)), Some(&|| d(m::nearbyint(-0.0))), Res::F64),
        ("fabs(-1e-310)", &|| d(m::fabs(-1e-310)), None, Res::Kept),
        ("copysign(1e-310,-1)", &|| d(m::copysign(1e-310, -1.0)), None, Res::Kept),
        ("fmax(1e-310,-1)", &|| d(m::fmax(1e-310, -1.0)), Some(&|| d(m::fmax(0.0, -1.0))), Res::Kept),
        ("fminf(-1e-40,1)", &|| f(m::fminf(-1e-40, 1.0)), Some(&|| f(m::fminf(-0.0, 1.0))), Res::Kept),
        ("fminmag(1e-310,2e-310)", &|| d(m::fminmag(1e-310, 2e-310)), Some(&|| d(m::fminmag(0.0, 0.0))), Res::Kept),
        ("fmaximum(1e-310,-1)", &|| d(m::fmaximum(1e-310, -1.0)), None, Res::Kept),
        ("fminimum_num(1e-310,0)", &|| d(m::fminimum_num(1e-310, 0.0)), Some(&|| d(1e-310)), Res::Kept),
        ("fminimum_mag_num(-1e-310,1)", &|| d(m::fminimum_mag_num(-1e-310, 1.0)), None, Res::Kept),
        ("fmaximum_magf(-1e-40,0)", &|| f(m::fmaximum_magf(-1e-40, 0.0)), Some(&|| 0), Res::Kept),
        ("fmax(2,3)", &|| d(m::fmax(2.0, 3.0)), None, Res::F64),
        ("remainder(1e-307,3e-308)", &|| d(m::remainder(1e-307, 3e-308)), None, Res::F64),
        ("fmod(1e-300,3e-310)", &|| d(m::fmod(1e-300, 3e-310)), Some(&|| d(m::fmod(1e-300, 0.0))), Res::F64),
        ("hypot(1e-310,1e-310)", &|| d(m::hypot(1e-310, 1e-310)), Some(&|| d(m::hypot(0.0, 0.0))), Res::F64),
        ("logb(1e-310)", &|| d(m::logb(1e-310)), Some(&|| d(m::logb(0.0))), Res::F64),
        ("lrint(1e-310)", &|| m::lrint(1e-310).cast_unsigned(), Some(&|| m::lrint(0.0).cast_unsigned()), Res::Int),
        ("ilogb(1e-310)", &|| u64::from(m::ilogb(1e-310).cast_unsigned()), Some(&|| u64::from(m::ilogb(0.0).cast_unsigned())), Res::Int),
        ("fromfp(1e-310,up,8)", &|| m::fromfp(1e-310, 0, 8).cast_unsigned(), Some(&|| m::fromfp(0.0, 0, 8).cast_unsigned()), Res::Int),
        ("lround(2.5)", &|| m::lround(2.5).cast_unsigned(), None, Res::Int),
        ("remquo(1e-307,3e-308)", &|| d(m::remquo(1e-307, 3e-308, Some(&mut 0))), None, Res::F64),
        ("modf(-1e-310)", &|| d(m::modf(-1e-310, Some(&mut 0.0))), Some(&|| d(m::modf(-0.0, Some(&mut 0.0)))), Res::F64),
        ("frexp(1e-310)", &|| d(m::frexp(1e-310, Some(&mut 0))), Some(&|| d(m::frexp(0.0, Some(&mut 0)))), Res::F64),
    ];
    let flush = |b: u64, r: Res| -> Option<u64> {
        let (exp, sign) = match r {
            Res::F64 => (0x7ff0_0000_0000_0000, 1 << 63),
            Res::F32 => (0x7f80_0000, 1 << 31),
            Res::Int | Res::Kept => return None,
        };
        (b & exp == 0 && b & !sign != 0).then_some(b & sign)
    };
    let mut flushed = 0;
    for (name, call, daz, r) in cases {
        for rc in 0..4u32 {
            let base = 0x1f80 | (rc << 13);
            for bit in [0x8000, 0x40, 0x8040] {
                let (want, mx) = match daz {
                    Some(g) if bit & 0x40 != 0 => around(base, g),
                    _ => around(base, call),
                };
                let (want, mx) = match flush(want, r) {
                    Some(z) if bit & 0x8000 != 0 => {
                        flushed += 1;
                        (z, mx | 0x30)
                    }
                    _ => (want, mx),
                };
                let (v, got) = around(base | bit, call);
                assert_eq!((name, rc, bit, v, got & !2), (name, rc, bit, want, (mx | bit) & !2));
            }
        }
    }
    // The table reaches the flush: the cases with subnormal default-word results are subnormal.
    assert!(flushed >= 100, "{flushed}");
    assert_eq!(around(0x1f80, || d(m::ldexp(1.0, -1070))), (1 << 4, 0x1f80));
    assert_eq!(around(0x1f80, || f(m::fadd(1e-39, 1e-39))).0 & 0x7f80_0000, 0);
    // The tininess edge through a software path (D-10.22, FPENV-HONOR-2): hypot of these two
    // subnormals is the smallest normal, tiny after rounding (underflow under the default word),
    // and is flushed under the caller's FTZ; a smallest normal that is not tiny is kept.
    let (x, y) = (f64::from_bits((1 << 52) - 1), f64::from_bits((1 << 26) + (1 << 23)));
    let edge = f64::MIN_POSITIVE.to_bits();
    assert_eq!(around(0x1f80, || d(m::hypot(x, y))), (edge, 0x1fb0));
    assert_eq!(around(0x9f80, || d(m::hypot(x, y))), (0, 0x9fb0));
    assert_eq!(around(0x9f80, || d(m::ldexp(1.0, -1022))), (edge, 0x9f80));
    assert_eq!(around(0x9f80, || d(m::fma(f64::MIN_POSITIVE, 1.0, 0.0))), (edge, 0x9f80));
    fpu::clear(&CSys, Flags::ALL);
}

