/// `hypotf` in MXCSR direction `rc` (0 nearest, 1 down, 2 up, 3 toward zero): the result's bits,
/// the IEEE flags it raised (the denormal-operand bit aside) and `errno`.
#[allow(clippy::as_conversions, clippy::arithmetic_side_effects, clippy::cast_possible_truncation, clippy::cast_sign_loss, clippy::cast_precision_loss, clippy::cast_possible_wrap, clippy::float_arithmetic, clippy::integer_division)] // bit-level test arithmetic on bounded values
fn hypotf_in(rc: u32, f: impl FnOnce() -> f32) -> (u64, u32, i32) {
    liella_boundary::errno::set_raw(0);
    let (v, after) = around(0x1f80 | rc << 13, || u64::from(f().to_bits()));
    (v, after & 0x3d, liella_boundary::errno::get())
}

#[test]
#[allow(clippy::as_conversions, clippy::arithmetic_side_effects, clippy::cast_possible_truncation, clippy::cast_sign_loss, clippy::cast_precision_loss, clippy::cast_possible_wrap, clippy::float_arithmetic, clippy::integer_division)] // bit-level test arithmetic on bounded values
fn math_hypotf_fast_path_is_the_accurate_hypotf() {
    // Clauses: s10_0_f_0, s10_0_c_0. #1541: the fast path's bits, flags and errno are the
    // correctly rounded path's in every direction (exact roots included: they raise nothing);
    // roots on a float midpoint, overflow, subnormal results and NaN/infinity operands reach
    // the accurate path.
    use liella_boundary::mathret as mr;
    let mut pairs: Vec<(f32, f32)> = vec![
        (3.0, 4.0), (-7.0, 24.0), (1.0, 1.0), (f32::MAX, f32::MAX), (f32::MAX, 1.0), (1.0, 2f32.powi(-12)),
        (f32::MIN_POSITIVE, f32::MIN_POSITIVE), (1e-45, 1e-45), (5e-39, 3e-39), (0.0, -0.0),
        (f32::INFINITY, f32::NAN), (f32::NAN, 1.0), (1e30, 1e-30), (2.5e19, 2.5e19), (1.8e19, 1.8e19),
    ];
    // The rounding boundary: roots within one double ulp of a float midpoint m (x in [1, 2),
    // y near 2^-11.5 x^(1/2), found by an exact integer search). x^2 + y^2 rounds to m^2 in
    // nearest, the double root is m exactly and ties-to-even picks the wrong float: only the
    // exact-midpoint test sends these to the accurate path (true root above m for the 1st and 3rd pair,
    // below for the 2nd and 4th).
    for (xb, yb) in [(0x3f80_0072u32, 0x39b5_0544u32), (0x3f80_0083, 0x39b5_0550), (0x3f80_01fe, 0x39b5_065c), (0x3f80_0261, 0x39b5_06a2)] {
        pairs.push((f32::from_bits(xb), f32::from_bits(yb)));
        pairs.push((-f32::from_bits(yb), f32::from_bits(xb)));
    }
    let mut s: u64 = 0x9e37_79b9_7f4a_7c15;
    for i in 0..40_000u32 {
        s ^= s << 13;
        s ^= s >> 7;
        s ^= s << 17;
        let (a, b) = ((s >> 32) as u32, s as u32);
        // Every third pair shares the first operand's exponent: the sum then rounds least.
        pairs.push(if i % 3 == 0 { (f32::from_bits(a), f32::from_bits((a & 0xff80_0000) | (b & 0x7f_ffff))) } else { (f32::from_bits(a), f32::from_bits(b)) });
    }
    // The fast-path rate is counted over operands of comparable magnitude (biased exponents
    // within 8 of each other, 2..=0xfd: the root is then a normal float). Operands further
    // apart make y² vanish in x² + y² (the double root is then |x| or its neighbour, still
    // decided on the fast path), but they are most random bit-pattern pairs and would swamp the rate.
    let comparable = |x: f32, y: f32| {
        let (ex, ey) = ((x.to_bits() >> 23) & 0xff, (y.to_bits() >> 23) & 0xff);
        (2..=0xfd).contains(&ex) && (2..=0xfd).contains(&ey) && ex.abs_diff(ey) <= 8
    };
    let (mut fast, mut eligible) = (0usize, 0usize);
    for rc in 0..4u32 {
        for &(x, y) in &pairs {
            let got = hypotf_in(rc, || m::hypotf(x, y));
            let want = hypotf_in(rc, || mr::ret(liella_math::pow::hypot(x, y, mr::mode())));
            assert_eq!(got, want, "hypotf({x:e}, {y:e}) in direction {rc}");
            if comparable(x, y) {
                eligible += 1;
                if hypotf_in(rc, || mr::hypotf_fast(x, y).unwrap_or(f32::NAN)).0 == got.0 {
                    fast += 1;
                }
            }
        }
    }
    assert_eq!(hypotf_in(0, || m::hypotf(3.0, 4.0)), (u64::from(5f32.to_bits()), 0, 0));
    assert_eq!(hypotf_in(0, || m::hypotf(f32::MAX, f32::MAX)), (u64::from(f32::INFINITY.to_bits()), 0x28, 34));
    // #1561, settled by a black-box probe of the reference (glibc 2.39): toward zero and
    // downward the overflowing root rounds to FLT_MAX with overflow and inexact raised and
    // errno left 0; upward a root just above FLT_MAX is infinity with ERANGE.
    let fmax = u64::from(f32::MAX.to_bits());
    assert_eq!(hypotf_in(3, || m::hypotf(f32::MAX, f32::MAX)), (fmax, 0x28, 0));
    assert_eq!(hypotf_in(1, || m::hypotf(f32::MAX, f32::MAX)), (fmax, 0x28, 0));
    assert_eq!(hypotf_in(3, || m::hypotf(f32::MAX, 1.0)), (fmax, 0x20, 0));
    assert_eq!(hypotf_in(2, || m::hypotf(f32::MAX, 1.0)), (u64::from(f32::INFINITY.to_bits()), 0x28, 34));
    // Finite random operands of comparable magnitude overwhelmingly take the fast path.
    assert!(eligible > 40_000 && fast * 10 > eligible * 9, "fast path taken {fast} of {eligible} comparable");
    fpu::clear(&CSys, Flags::ALL);
}

#[test]
#[allow(clippy::as_conversions, clippy::arithmetic_side_effects, clippy::cast_precision_loss, clippy::float_arithmetic)] // test operand arithmetic
fn math_double_invtrig_hypot_fast_tier_is_the_accurate_path() {
    // Clauses: s10_0_f_0, s10_0_c_0. LIBM-F64-INVTRIG-HYPOT-TIER: the `double` atan, asin, acos,
    // atan2 and hypot entries (fast tier in the default MXCSR, accurate path otherwise) give the
    // accurate path's bits, flags and errno in every direction as an entry delivers them: the
    // envelope `mr::elem` (the pre-story entry), which runs the double-double arithmetic in the
    // default MXCSR (under the caller's directed hardware rounding it is not exact) and drops
    // what that arithmetic raised in hardware but the result does not (acos(5e-324)'s steps
    // underflow, its result π/2 is not tiny). Every flag set also obeys §10.0 and C F.10 on its
    // own (`annex_f`): underflow exactly for a tiny inexact result, overflow and ERANGE only as
    // §10.0 says, invalid and EDOM only for a domain error. An exact root raises nothing, and
    // atan(1/2), whose fast-tier arithmetic is exact up to the last addition, raises inexact.
    use liella_boundary::mathret as mr;
    use liella_math::{pow, trig};
    let d_in = |rc: u32, f: &dyn Fn() -> f64| {
        liella_boundary::errno::set_raw(0);
        let (v, after) = around(0x1f80 | rc << 13, || f().to_bits());
        (v, after & 0x3d, liella_boundary::errno::get())
    };
    // The entry against the accurate path's envelope, then the spec rule on the entry's own.
    let check = |what: &str, rc: u32, args: &[f64], entry: &dyn Fn() -> f64, envelope: &dyn Fn() -> f64| {
        let got = d_in(rc, entry);
        assert_eq!(got, d_in(rc, envelope), "{what} in direction {rc}: (bits, flags, errno) against the accurate path");
        assert_eq!(annex_f(args, f64::from_bits(got.0), got.1, got.2), Ok(()), "{what} in direction {rc}: §10.0 flags (bits {:#x}, flags {:#x}, errno {})", got.0, got.1, got.2);
    };
    let tiny = [5e-324, -5e-324, 1e-323, f64::MIN_POSITIVE, -f64::MIN_POSITIVE, 2.225_073_858_507_201e-308, 1e-300, -1e-160, 1e-155];
    let mut xs = vec![0.5, 1.0, -1.0, 0.3, -0.7, 2.5, -1e10, 1e-10, 0.999_999_9, 1e-20, 1e300, 0.0, -0.0, 1.5, f64::INFINITY, f64::NAN];
    xs.extend_from_slice(&tiny);
    let mut pairs: Vec<(f64, f64)> = vec![(3.0, 4.0), (1.0, 2f64.powi(-30)), (0.5, 0.25), (-2.0, 3.0), (1e300, 1e300), (f64::MAX, f64::MAX), (1e-300, 1e-300), (5e-324, 1.0), (1.0, 5e-324), (5e-324, 0.0), (5e-324, 5e-324), (1e-300, 1e10), (-1e-300, 1e20), (f64::INFINITY, f64::NAN), (0.0, -0.0)];
    let mut s: u64 = 0x9e37_79b9_7f4a_7c15;
    for i in 0..3000u32 {
        s ^= s << 13;
        s ^= s >> 7;
        s ^= s << 17;
        let x = f64::from_bits(s) % 4.0;
        xs.push(if i % 2 == 0 { x * 0.25 } else { x * 1e5 });
        pairs.push((x, f64::from_bits(s.rotate_left(17)) % 9.0));
    }
    for rc in 0..4u32 {
        for &x in &xs {
            check(&format!("atan({x:e})"), rc, &[x], &|| m::atan(x), &|| mr::elem(x, mr::Unit::Sse, trig::atan::<f64>));
            check(&format!("asin({x:e})"), rc, &[x], &|| m::asin(x), &|| mr::elem(x, mr::Unit::Sse, trig::asin::<f64>));
            check(&format!("acos({x:e})"), rc, &[x], &|| m::acos(x), &|| mr::elem(x, mr::Unit::Sse, trig::acos::<f64>));
        }
        for &(y, x) in &pairs {
            for (y, x) in [(y, x), (x, y)] {
                check(&format!("atan2({y:e}, {x:e})"), rc, &[y, x], &|| m::atan2(y, x), &|| mr::elem((y, x), mr::Unit::Sse, |(y, x), md| trig::atan2::<f64>(y, x, md)));
                check(&format!("hypot({y:e}, {x:e})"), rc, &[y, x], &|| m::hypot(y, x), &|| mr::elem((y, x), mr::Unit::Sse, |(y, x), md| pow::hypot::<f64>(y, x, md)));
            }
        }
    }
    // The case run -3's FULL gate found (the raw computation raises underflow in hardware), in
    // every direction and for both signs: π/2 rounded, inexact only.
    for rc in 0..4u32 {
        for x in [5e-324, -5e-324] {
            let (v, flags, errno) = d_in(rc, &|| m::acos(x));
            assert!((f64::from_bits(v) - core::f64::consts::FRAC_PI_2).abs() < 1e-15 && flags == 0x20 && errno == 0, "acos({x:e}) in direction {rc}: ({v:#x}, {flags:#x}, {errno})");
        }
    }
    assert_eq!(d_in(0, &|| m::hypot(3.0, 4.0)), (5f64.to_bits(), 0, 0), "hypot(3, 4) exact-root flags");
    assert_eq!(d_in(0, &|| m::hypot(1.0, 2f64.powi(-30))), (1f64.to_bits(), 0x20, 0), "hypot(1, 2^-30) must raise inexact");
    assert_eq!(d_in(0, &|| m::atan(0.5)).1, 0x20, "atan(1/2) must raise inexact");
    fpu::clear(&CSys, Flags::ALL);
}

/// §10.0 (s10_0_f_0) and C F.10 for a `double` result `r` of the operands `args` (quiet NaNs,
/// infinities or finite values), its MXCSR flags (`0x3d` bits: invalid, divide-by-zero, overflow,
/// underflow, inexact) and `errno`, decided from the result alone: invalid and `EDOM` exactly for
/// a NaN from non-NaN operands; never divide-by-zero; underflow only for an inexact result at or
/// below the smallest normal and always for an inexact one below it (tininess is detected after
/// rounding, so a result rounded up to `DBL_MIN` may carry it); overflow only for an inexact
/// result of finite operands that is infinite or `DBL_MAX`, and always for an infinite one;
/// `ERANGE` exactly for an overflow to ±∞ or an underflow to ±0.
#[allow(clippy::float_cmp)] // exact comparisons against the format's limits
fn annex_f(args: &[f64], r: f64, flags: u32, errno: i32) -> Result<(), String> {
    const EDOM: i32 = 33;
    const ERANGE: i32 = 34;
    let finite = args.iter().all(|a| a.is_finite());
    let domain = r.is_nan() && !args.iter().any(|a| a.is_nan());
    let inexact = flags & 0x20 != 0;
    let (uf, of) = (flags & 0x10 != 0, flags & 0x08 != 0);
    if (flags & 0x01 != 0) != domain {
        return Err(format!("invalid must be raised exactly for a domain error (domain: {domain})"));
    }
    if flags & 0x04 != 0 {
        return Err("divide-by-zero raised".into());
    }
    if uf && !(inexact && r.abs() <= f64::MIN_POSITIVE) {
        return Err("underflow raised for a result that is exact or not tiny".into());
    }
    if !uf && inexact && r.abs() < f64::MIN_POSITIVE {
        return Err("underflow missing for a tiny inexact result".into());
    }
    if of && !(inexact && finite && (r.is_infinite() || r.abs() == f64::MAX)) {
        return Err("overflow raised for a result that did not overflow".into());
    }
    if !of && finite && r.is_infinite() {
        return Err("overflow missing for an infinite result of finite operands".into());
    }
    let range = finite && (r.is_infinite() || (r == 0.0 && inexact));
    let want = if domain { EDOM } else if range { ERANGE } else { 0 };
    if errno != want {
        return Err(format!("errno {errno}, §10.0 gives {want}"));
    }
    Ok(())
}

/// Whether `f` is √(x²+y²) rounded in MXCSR direction `rc` (0 nearest, 1 down, 2 up, 3 toward
/// zero): the root inside the rounding interval, or exactly `f` (an exact root), decided in
/// integers: the squares of the interval ends against x²+y², in units of a quarter `f` ulp.
#[allow(clippy::as_conversions, clippy::arithmetic_side_effects, clippy::cast_possible_truncation, clippy::cast_sign_loss, clippy::cast_precision_loss, clippy::cast_possible_wrap, clippy::float_arithmetic, clippy::integer_division)] // bit-level test arithmetic on bounded values
fn hypotf_oracle(x: f32, y: f32, f: f32, rc: u32) -> bool {
    let parts = |v: f32| -> (u128, i32) {
        let b = v.to_bits() & 0x7fff_ffff;
        let (e, m) = ((b >> 23) as i32, u128::from(b & 0x7f_ffff));
        if e == 0 { (m, -149) } else { (m | 0x80_0000, e - 150) }
    };
    let (mf, ef) = parts(f);
    if f.to_bits() >> 23 == 0 || f.to_bits() >> 23 >= 0xff {
        return false; // the fast path returns positive normal floats only
    }
    let q = 4 * mf;
    let (lo, hi) = match rc {
        0 => (if mf == 1 << 23 { q - 1 } else { q - 2 }, q + 2),
        1 | 3 => (q, q + 4),
        _ => (if mf == 1 << 23 { q - 2 } else { q - 4 }, q),
    };
    let (mut sum, mut sticky) = (0u128, false);
    for v in [x, y] {
        let (mv, ev) = parts(v);
        if mv == 0 {
            continue;
        }
        let sq = mv * mv;
        let k = 2 * (ev - ef) + 4 + 64;
        if k >= 0 {
            if k as u32 + 4 >= sq.leading_zeros() {
                return false; // this square alone is far above hi²
            }
            sum += sq << k;
        } else if -k >= 128 {
            sticky = true;
        } else {
            sum += sq >> -k;
            sticky |= sq & ((1u128 << -k) - 1) != 0;
        }
    }
    let (lo2, hi2) = ((lo * lo) << 64, (hi * hi) << 64);
    // The true root t has t² = sum + (a positive fraction iff sticky). An exact root t = f is
    // right in every direction: the directed intervals are closed at f (downward and toward
    // zero t >= f, upward t <= f), the nearest one is open at both midpoints.
    let above_lo = sum > lo2 || (sum == lo2 && (sticky || rc == 1 || rc == 3));
    let below_hi = sum < hi2 || (sum == hi2 && !sticky && rc == 2);
    above_lo && below_hi
}

/// The one-pass `float` entries (LIBM-F32-ONEPASS, D-10.63) and their reference: the full
/// envelope on the accurate path, the entry they replaced.
type OnePass = (&'static str, extern "C" fn(f32) -> f32, fn(f32) -> f32);
const ONEPASS: [OnePass; 9] = [
    ("expf", m::expf, |x| liella_boundary::mathret::elem(x, liella_boundary::mathret::Unit::Sse, liella_math::real::Real::exp)),
    ("exp2f", m::exp2f, |x| liella_boundary::mathret::elem(x, liella_boundary::mathret::Unit::Sse, liella_math::real::Real::exp2)),
    ("exp10f", m::exp10f, |x| liella_boundary::mathret::elem(x, liella_boundary::mathret::Unit::Sse, liella_math::real::Real::exp10)),
    ("logf", m::logf, |x| liella_boundary::mathret::elem(x, liella_boundary::mathret::Unit::Sse, liella_math::real::Real::log)),
    ("log2f", m::log2f, |x| liella_boundary::mathret::elem(x, liella_boundary::mathret::Unit::Sse, liella_math::real::Real::log2)),
    ("log10f", m::log10f, |x| liella_boundary::mathret::elem(x, liella_boundary::mathret::Unit::Sse, liella_math::real::Real::log10)),
    ("asinf", m::asinf, |x| liella_boundary::mathret::elem(x, liella_boundary::mathret::Unit::Sse, liella_math::real::Real::asin)),
    ("acosf", m::acosf, |x| liella_boundary::mathret::elem(x, liella_boundary::mathret::Unit::Sse, liella_math::real::Real::acos)),
    ("atanf", m::atanf, |x| liella_boundary::mathret::elem(x, liella_boundary::mathret::Unit::Sse, liella_math::real::Real::atan)),
];

/// Compare `entry` with `reference` on the encoding `b` under MXCSR `mx`: result bits, errno
/// and flags. True when they differ (the first few are printed).
fn onepass_differs(p: &OnePass, mx: u32, b: u32, printed: u64) -> bool {
    let (name, entry, reference) = *p;
    let x = f32::from_bits(b);
    let (mut got, mut want) = (0u32, 0u32);
    let seen = observe_with_ctl(mx, || got = entry(x).to_bits());
    let wanted = observe_with_ctl(mx, || want = reference(x).to_bits());
    let differs = (got, seen) != (want, wanted);
    if differs && printed < 4 {
        eprintln!("BAD {name}({b:#010x}) mxcsr {mx:#06x}: got {got:#010x} {seen:?}, want {want:#010x} {wanted:?}");
    }
    differs
}

/// [`onepass_differs`] on every `stride`-th encoding of the chunk `c` (2^20 encodings).
/// Returns (calls, mismatches).
#[allow(clippy::arithmetic_side_effects)] // counters below 2^34; b steps inside its chunk
fn onepass_chunk(p: &OnePass, mx: u32, c: u32, stride: u32) -> (u64, u64) {
    let (mut n, mut bad) = (0u64, 0u64);
    let mut b = c << 20;
    loop {
        n += 1;
        bad += u64::from(onepass_differs(p, mx, b, bad));
        match b.checked_add(stride) {
            Some(nb) if nb >> 20 == c => b = nb,
            _ => break,
        }
    }
    (n, bad)
}

#[test]
#[allow(clippy::arithmetic_side_effects, clippy::as_conversions, clippy::cast_possible_truncation)] // bit fields and counters of bounded width
fn math_expf_onepass_entries_match_the_envelope() {
    // Clauses: s10_0_f_0. D-10.63: the entries that run in the caller's MXCSR unread give the
    // envelope's bits, errno and flags in every rounding direction and under FTZ, DAZ and both
    // (D-10.22), on a sample of every chunk of the encodings, and on the operands at the edges of
    // the one-pass range, the exact results and the special values.
    // D-10.72 adds exp10f's range edges (±37.9) and exact powers (1, 9, 10; 11 and 1.125 are not
    // exact), and the log family's: 1 and its neighbours, the m split at 0.75 and 1.5, the least
    // normal and the largest finite operand, -1, and the 10^n operands log10 refuses (10, 10^10).
    let edges: [u32; 44] = [
        0x0000_0000, 0x8000_0000, 0x0000_0001, 0x807f_ffff, 0x327f_ffff, 0x3280_0000, 0xb280_0000, 0x42ae_a8f5,
        0x42ae_a8f6, 0xc2ae_a8f6, 0x42fb_ffff, 0x42fc_0000, 0xc2fc_0000, 0x4040_0000, 0xc0e0_0000, 0x7f80_0000,
        0xff80_0000, 0x7fc0_0000, 0x7f80_0001, 0xffa0_0005, 0x4217_9999, 0x4217_999a, 0xc217_999a, 0x3f80_0000,
        0x4110_0000, 0x4120_0000, 0x4130_0000, 0x3f90_0000, 0x3f7f_ffff, 0x3f80_0001, 0x3f40_0000, 0x3fc0_0000,
        0x0080_0000, 0x7f7f_ffff, 0xbf80_0000, 0x5015_02f9,
        // D-10.82 (asinf, acosf, atanf): the one-pass ranges' edges (|x| < 1, the least and the
        // largest normal), the index split at s = 1/64 and 1/8, and 1 - 2^-24 on both sides.
        0x3f7f_ffff, 0xbf7f_ffff, 0x3c80_0000, 0x3c7f_ffff, 0x3e00_0000, 0x0080_0001, 0x807f_ffff, 0xff7f_ffff,
    ];
    for p in &ONEPASS {
        for ctl in [0u32, 0x8000, 0x0040, 0x8040] {
            for rc in 0..4u32 {
                let mx = 0x1f80 | ctl | rc << 13;
                let mut bad = 0;
                for c in 0..1u32 << 12 {
                    bad += onepass_chunk(p, mx, c, 0x3_fffb).1;
                }
                for &b in &edges {
                    bad += u64::from(onepass_differs(p, mx, b, bad));
                }
                assert_eq!(bad, 0, "{} differs from the envelope under MXCSR {mx:#06x}", p.0);
            }
        }
    }
}

/// Every `float` encoding (or every `LIELLA_SWEEP_STRIDE`-th) in the four directions.
#[allow(clippy::arithmetic_side_effects, clippy::as_conversions, clippy::cast_possible_truncation)] // bit fields and counters of bounded width
fn onepass_sweep(p: &OnePass) {
    use std::sync::atomic::{AtomicU64, Ordering::Relaxed};
    let stride = std::env::var("LIELLA_SWEEP_STRIDE").ok().and_then(|s| s.parse().ok()).unwrap_or(1u32);
    let threads = std::thread::available_parallelism().map_or(4, |n| n.get());
    let (next, calls, bad) = (AtomicU64::new(0), AtomicU64::new(0), AtomicU64::new(0));
    std::thread::scope(|sc| {
        for _ in 0..threads {
            sc.spawn(|| loop {
                let c = next.fetch_add(1, Relaxed);
                if c >= 1 << 14 {
                    break;
                }
                let (n, b) = onepass_chunk(p, 0x1f80 | ((c as u32) & 3) << 13, (c >> 2) as u32, stride);
                calls.fetch_add(n, Relaxed);
                bad.fetch_add(b, Relaxed);
            });
        }
    });
    let (n, b) = (calls.load(Relaxed), bad.load(Relaxed));
    println!("{} one-pass sweep: stride {stride}, calls {n} (4 directions), mismatches {b}", p.0);
    assert_eq!(n, (1u64 << 14) * (1u64 << 20).div_ceil(u64::from(stride)), "every chunk checked once");
    assert_eq!(b, 0, "{} differs from the envelope", p.0);
}

